        q("waec-chem-environment-002","chem-pollution","Which treatment is most directly used to reduce suspended solids in wastewater?",listOf("Sedimentation followed by filtration","Adding petrol","Increasing water temperature only","Open-air burning"),0,"Settling and filtration remove suspended particulate matter from wastewater."),
